import * as THREE from 'three/webgpu';
import { tslFn, mix, uv, vec2, mul } from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import textUtils from '@/text';

/**
 * @param {Object} config
 * @param {Object} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // Root group
    const root = new THREE.Group();
    if (config.position) root.position.fromArray(config.position);
    if (config.rotation) root.rotation.fromArray(config.rotation);
    if (config.scale) root.scale.fromArray(config.scale);

    // -----------------------------------------------------------------
    // Backdrop
    // -----------------------------------------------------------------
    const backdropGeo = new THREE.PlaneGeometry(7, 5.5);
    const gradientNode = tslFn(() => {
        const c0 = new THREE.Color('#0b0b10');
        const c1 = new THREE.Color('#13131a');
        return mix(c0, c1, uv().y);
    });
    const backdropMat = new THREE.MeshStandardMaterial({
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
    });
    backdropMat.colorNode = gradientNode;
    const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
    backdrop.position.set(0, 0, -1.5);
    root.add(backdrop);

    // -----------------------------------------------------------------
    // Helper: create MSDF glyph mesh
    // -----------------------------------------------------------------
    const createGlyphMesh = (char, style, zOffset) => {
        const glyph = ctx.fontAtlas.getGlyph(char);
        const tex = ctx.fontAtlas.texture;
        const emHeight = style.emHeight; // scene units
        const scale = emHeight / glyph.height; // assume glyph.height is in texture pixel units
        const width = glyph.width * scale;
        const height = glyph.height * scale;

        const geo = new THREE.PlaneGeometry(width, height);
        // adjust UVs to glyph rect
        const uvAttr = geo.attributes.uv;
        const uvs = uvAttr.array;
        const { u0, v0, u1, v1 } = glyph.uvRect; // normalized
        // each vertex has (u, v)
        for (let i = 0; i < uvs.length; i += 2) {
            const x = uvs[i];
            const y = uvs[i + 1];
            // map from 0‑1 quad to glyph uv rect
            uvs[i] = u0 + (u1 - u0) * x;
            uvs[i + 1] = v0 + (v1 - v0) * y;
        }
        uvAttr.needsUpdate = true;

        const mat = new THREE.MeshBasicMaterial({
            map: tex,
            transparent: true,
            depthWrite: false,
            color: new THREE.Color('#16161d'),
            opacity: 0,
        });

        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.z = zOffset;
        return mesh;
    };

    // -----------------------------------------------------------------
    // HERO TEXT: "TIME, MACHINED."
    // -----------------------------------------------------------------
    const heroSpec = {
        text: 'TIME, MACHINED.',
        style: {
            family: 'Lora',
            fontWeight: 600,
            emHeight: 0.62,
            letterSpacing: -0.01,
        },
        y: 0.4,
        wordZOffsets: [0.12, 0, -0.12],
        riseUnits: 0.35,
        staggerMs: 60,
    };

    const heroGroup = new THREE.Group();
    heroGroup.position.y = heroSpec.y;
    root.add(heroGroup);

    // Split into words to apply per‑word Z offsets
    const words = heroSpec.text.split(' ');
    const glyphMeshes = [];
    let cursorX = 0;
    let wordIdx = 0;

    for (let w = 0; w < words.length; w++) {
        const word = words[w];
        const zOffset = heroSpec.wordZOffsets[wordIdx % heroSpec.wordZOffsets.length];
        for (let i = 0; i < word.length; i++) {
            const char = word[i];
            const mesh = createGlyphMesh(char, heroSpec.style, zOffset);
            // apply letterSpacing (scene units)
            const ls = heroSpec.style.letterSpacing * heroSpec.style.emHeight;
            mesh.position.x = cursorX;
            mesh.position.y = heroSpec.riseUnits; // start offset
            heroGroup.add(mesh);
            glyphMeshes.push(mesh);
            cursorX += mesh.geometry.parameters.width + ls;
        }
        // add space width (approximate as emHeight * 0.3)
        const spaceWidth = heroSpec.style.emHeight * 0.3;
        cursorX += spaceWidth;
        wordIdx++;
    }

    // Center hero group horizontally
    heroGroup.position.x = -cursorX / 2 + (heroSpec.style.emHeight * 0.15);

    // -----------------------------------------------------------------
    // Underline
    // -----------------------------------------------------------------
    const underlineGeom = new THREE.PlaneGeometry(2.6, 0.045);
    // Pivot left side
    underlineGeom.translate(1.3, 0, 0);
    const underlineMat = new THREE.MeshStandardMaterial({
        color: new THREE.Color('#ff2a38'),
        emissive: new THREE.Color('#ff2a38'),
        emissiveIntensity: 1.2,
        transparent: true,
        depthWrite: false,
    });
    const underline = new THREE.Mesh(underlineGeom, underlineMat);
    underline.position.set(-heroGroup.position.x, -0.05, 0);
    underline.scale.x = 0;
    heroGroup.add(underline);

    // -----------------------------------------------------------------
    // Subhead
    // -----------------------------------------------------------------
    const subheadSpec = {
        text: 'Every calibre begins as a solid billet.',
        style: {
            family: 'JetBrains Mono',
            fontWeight: 400,
            emHeight: 0.2,
            letterSpacing: 0.02,
        },
        y: -0.65,
    };
    const subheadGroup = new THREE.Group();
    subheadGroup.position.y = subheadSpec.y;
    root.add(subheadGroup);

    const subheadGlyphs = [];
    let subCursorX = 0;
    for (let i = 0; i < subheadSpec.text.length; i++) {
        const char = subheadSpec.text[i];
        const mesh = createGlyphMesh(char, subheadSpec.style, 0);
        const ls = subheadSpec.style.letterSpacing * subheadSpec.style.emHeight;
        mesh.position.x = subCursorX;
        mesh.position.y = 0.2; // start offset for fade‑up
        mesh.material.opacity = 0;
        subheadGroup.add(mesh);
        subheadGlyphs.push(mesh);
        subCursorX += mesh.geometry.parameters.width + ls;
    }
    subheadGroup.position.x = -subCursorX / 2 + (subheadSpec.style.emHeight * 0.15);

    // -----------------------------------------------------------------
    // Caption (kicker)
    // -----------------------------------------------------------------
    const captionSpec = {
        text: 'NOVA ATELIER / CALIBRE PROGRAM',
        style: {
            family: 'JetBrains Mono',
            fontWeight: 700,
            emHeight: 0.09,
            letterSpacing: 0.12,
        },
        y: 1.15,
    };
    const captionGroup = new THREE.Group();
    captionGroup.position.y = captionSpec.y;
    root.add(captionGroup);

    const captionGlyphs = [];
    let capCursorX = 0;
    const captionText = captionSpec.text.toUpperCase();
    for (let i = 0; i < captionText.length; i++) {
        const char = captionText[i];
        const mesh = createGlyphMesh(char, captionSpec.style, 0);
        const ls = captionSpec.style.letterSpacing * captionSpec.style.emHeight;
        mesh.position.x = capCursorX;
        mesh.position.y = 0;
        captionGroup.add(mesh);
        captionGlyphs.push(mesh);
        capCursorX += mesh.geometry.parameters.width + ls;
    }
    captionGroup.position.x = -capCursorX / 2 + (captionSpec.style.emHeight * 0.15);

    // -----------------------------------------------------------------
    // GSAP Timelines
    // -----------------------------------------------------------------
    const timelines = [];

    // Hero kinetic entrance
    const heroTL = gsap.timeline();
    timelines.push(heroTL);
    heroTL.from(
        glyphMeshes.map(m => m.position),
        {
            y: 0,
            duration: 0.7,
            ease: 'cubic-bezier(0.215,0.61,0.355,1)',
            stagger: heroSpec.staggerMs / 1000,
        },
        0
    );
    heroTL.from(
        glyphMeshes.map(m => m.material),
        {
            opacity: 0,
            duration: 0.7,
            ease: 'cubic-bezier(0.215,0.61,0.355,1)',
            stagger: heroSpec.staggerMs / 1000,
        },
        0
    );
    // Weighted settle on whole group after last glyph
    heroTL.to(
        heroGroup.scale,
        {
            x: 1.04,
            y: 1.04,
            z: 1.04,
            duration: 0.9,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        },
        '+=0'
    );
    heroTL.to(
        heroGroup.scale,
        {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.9,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        },
        '+=0'
    );

    // Underline reveal
    heroTL.add(
        gsap.to(underline.scale, {
            x: 1,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            delay: 0.12,
        })
    );

    // Subhead fade‑up (starts after underline)
    const subTL = gsap.timeline({ delay: heroTL.duration() });
    timelines.push(subTL);
    subTL.from(
        subheadGlyphs.map(m => m.position),
        {
            y: 0.2,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        0
    );
    subTL.from(
        subheadGlyphs.map(m => m.material),
        {
            opacity: 0,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        },
        0
    );

    // -----------------------------------------------------------------
    // Apply cinematic primitives listed in config
    // -----------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params ?? {});
            }
        }
    }

    // -----------------------------------------------------------------
    // Cleanup
    // -----------------------------------------------------------------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        timelines.forEach(tl => tl.kill());
        // dispose geometries and materials
        root.traverse(obj => {
            if (obj.isMesh) {
                if (obj.geometry) obj.geometry.dispose();
                if (obj.material) {
                    if (Array.isArray(obj.material)) {
                        obj.material.forEach(m => m.dispose());
                    } else {
                        obj.material.dispose();
                    }
                }
            }
        });
    };

    return root;
}
